+++ b/drivers/gpu/drm/etnaviv/etnaviv_sched.c
@@ -79,6 +79,11 @@ static enum drm_gpu_sched_stat etnaviv_sched_timedout_job(struct drm_sched_job
 	if(sched_job)
 		drm_sched_increase_karma(sched_job);
 
+	mutex_lock(&gpu->lock);
